import * as T from 'three';
import {overlapsCollider,safeConstructionPosition,prepareConstruction} from './build-safety.js';
const KEY='greyman-cozy-v1';
export function createLiving({world,character,camera,controls,harvesting,greyMan,toast,isWalking,grant}){
 let state;try{state=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{state={}};state={houses:{},crystals:{},crystalCount:0,bank:{wood:0,stone:0,crystals:0},runes:[false,false,false],puzzleReward:false,tool:0,...state};state.bank={wood:0,stone:0,crystals:0,...state.bank};
 const dialog=document.createElement('dialog');dialog.id='gameDialog';dialog.innerHTML='<div class="dialog-head"><h2 id="gameTitle"></h2><button id="closeGame" aria-label="Cerrar">✕</button></div><div id="gameContent"></div>';document.body.append(dialog);const content=dialog.querySelector('#gameContent');dialog.querySelector('#closeGame').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
 const count=document.createElement('span');count.innerHTML='Cristales <b id="crystalCount">0</b>';document.querySelector('.inventory').append(count);let extension=null,selected=null,crystalDelay=0,restTime=0,restedUntil=0,lastTarget=0;
 const marker=new T.Mesh(new T.RingGeometry(.45,.52,24),new T.MeshBasicMaterial({color:0xc2efcb,side:T.DoubleSide,transparent:true,opacity:.8,depthWrite:false}));marker.rotation.x=-Math.PI/2;marker.visible=false;world.root.add(marker);
 function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}harvesting.save();document.getElementById('crystalCount').textContent=state.crystalCount;}
 function houseState(h){return state.houses[h.id]||(state.houses[h.id]={stage:0,wood:0,stone:0})}
 const guide=world.layers.Colisiones.getObjectByName('Colliders_AABB');const identity=new T.Object3D();
 function updateGuides(){if(!guide)return;for(let i=0;i<Math.min(world.colliders.length,guide.count);i++){const c=world.colliders[i];identity.position.set(c.x,c.y,c.z);identity.scale.set(c.removed?0:c.w,c.removed?0:c.h,c.removed?0:c.d);identity.updateMatrix();guide.setMatrixAt(i,identity.matrix)}guide.instanceMatrix.needsUpdate=true;window.dispatchEvent(new Event('world-physics-changed'));}
 function setDoor(h,open){const c=character.position,leaf=open?h.opened:h.closed;if(Math.abs(c.x-leaf.x)<leaf.w/2+.5&&Math.abs(c.z-leaf.z)<leaf.d/2+.5){toast('Apártate un poco para mover la puerta.');return}h.open=open;h.closed.removed=open;h.opened.removed=!open;updateGuides();}
 for(const h of world.buildings)h.applyStage(Math.min(3,Math.max(0,houseState(h).stage||0)));
 for(const c of world.collectibles){if(Object.hasOwn(state.crystals,c.id)){c.hp=Math.max(0,state.crystals[c.id]);if(c.hp===0){c.group.visible=false;if(c.c)c.c.removed=true;}}}
 function glow(){for(let i=0;i<3;i++)for(const g of [world.runes[i],world.runeGlyphs[i]]){g.userData.glow.color.setHex(state.runes[i]?0xc1ffe2:0x77aaa1);g.userData.glow.emissiveIntensity=state.runes[i]?1.2:.1;}}
 glow();if(state.runes.every(Boolean))grant('quest:ruinas-restauradas');save();updateGuides();harvesting.damage=1+state.tool;
 function openPanel(title){window.dispatchEvent(new Event('construction-relocated'));document.getElementById('gameTitle').textContent=title;content.replaceChildren();if(!dialog.open)dialog.showModal();}
 function para(text){const p=document.createElement('p');p.textContent=text;content.append(p);return p;}
 function button(text,fn,disabled=false){const b=document.createElement('button');b.textContent=text;b.disabled=disabled;b.onclick=fn;content.append(b);return b;}
 function nearby(x,z,y=character.position.y,range=2.1){return Math.abs(character.position.y-y)<1.6&&Math.hypot(character.position.x-x,character.position.z-z)<range;}
 function requireNear(x,z,y,range=3){if(!isWalking()||!nearby(x,z,y,range)){dialog.close();toast('Acércate para utilizarlo.');return false}return true;}
 function moveSafely(destination){const delta=new T.Vector3(destination.x,destination.y,destination.z).sub(character.position);character.position.add(delta);camera.position.add(delta);controls.target.add(delta);window.dispatchEvent(new Event('construction-relocated'));}
 function repair(h){const hs=houseState(h),cost=h.costs[hs.stage];openPanel(h.name);para(`${h.use} · ${['Estructura abandonada','Muros reparados','Tejado reparado','Edificio funcional'][hs.stage]}`);
  if(hs.stage===3){para({home:'Entra y utiliza la cama para descansar y fijar tu hogar.',workshop:'Entra y acércate al banco para mejorar las herramientas.',store:'Entra y utiliza el cofre para guardar y retirar recursos.'}[h.id]);return}
  para(`Siguiente etapa: ${['cerrar los muros','reparar el tejado','amueblar el interior'][hs.stage]}.`);para(`Madera aportada: ${hs.wood}/${cost[0]} · Piedra aportada: ${hs.stone}/${cost[1]}`);para(`Llevas ${harvesting.inventory.wood} de madera y ${harvesting.inventory.stone} de piedra.`);
  button('Aportar materiales disponibles',()=>{if(!requireNear(h.x+2.7,h.z+h.d/2+1.8,2,3.2))return;const wood=Math.min(harvesting.inventory.wood,cost[0]-hs.wood),stone=Math.min(harvesting.inventory.stone,cost[1]-hs.stone);if(!wood&&!stone){toast('Necesitas madera o piedra para continuar.');return}const completes=hs.wood+wood>=cost[0]&&hs.stone+stone>=cost[1];let destination=null;if(completes){destination=prepareConstruction(world,h,hs.stage+1,character.position);if(!destination){toast('No hay espacio libre junto a la obra. Despeja el entorno para continuar.');return}}harvesting.inventory.wood-=wood;harvesting.inventory.stone-=stone;hs.wood+=wood;hs.stone+=stone;if(completes){hs.stage++;hs.wood=hs.stone=0;moveSafely(destination);updateGuides();toast(hs.stage===3?`${h.name}: ya funciona.`:'Etapa completada. Zona de obra despejada.')}window.dispatchEvent(new CustomEvent('life:activity',{detail:{skill:'building',xp:completes?35:wood+stone,count:completes?1:0}}));save();repair(h)});
 }
 function indoor(h){if(h.stage<3){toast('Completa la reparación para utilizar este edificio.');return}openPanel(h.name);
  if(h.id==='home'){para('Descansa para obtener vigor y fijar aquí el punto de regreso. El vigor añade un punto de fuerza de recolección durante tres minutos.');button('Descansar',()=>{if(!requireNear(h.interact.x,h.interact.z,2.12,2.5))return;state.home={x:h.x,z:h.z+h.d/2+2};window.dispatchEvent(new Event('life:rest'));restTime=2.5;restedUntil=Date.now()+180000;dialog.close();document.body.classList.add('resting');save();toast('Descansando…')});}
  if(h.id==='store'){para(`Guardado: ${state.bank.wood} madera · ${state.bank.stone} piedra · ${state.bank.crystals} cristales.`);para('Puedes transferir diez unidades o todo lo que tengas si llevas menos.');for(const [key,label]of [['wood','madera'],['stone','piedra'],['crystals','cristales']]){const carried=key==='crystals'?state.crystalCount:harvesting.inventory[key];button(`Guardar ${Math.min(10,carried)} ${label}`,()=>transfer(key,true),carried<=0);button(`Retirar ${Math.min(10,state.bank[key])} ${label}`,()=>transfer(key,false),state.bank[key]<=0)}
   function transfer(key,deposit){if(!requireNear(h.interact.x,h.interact.z,2.12,2.5))return;const carried=key==='crystals'?state.crystalCount:harvesting.inventory[key];const n=Math.min(10,deposit?carried:state.bank[key]);state.bank[key]+=deposit?n:-n;if(key==='crystals')state.crystalCount+=deposit?-n:n;else harvesting.inventory[key]+=deposit?-n:n;save();indoor(h)}
  }
  if(h.id==='workshop'){para(`Herramientas: nivel ${state.tool+1}. Fuerza por golpe: ${state.tool+1}.`);if(state.tool<2){const cost={wood:10+state.tool*10,stone:8+state.tool*8,crystals:3+state.tool*3};para(`Mejora: ${cost.wood} madera, ${cost.stone} piedra y ${cost.crystals} cristales.`);button('Mejorar hacha y pico',()=>{if(!requireNear(h.interact.x,h.interact.z,2.12,2.5))return;if(harvesting.inventory.wood<cost.wood||harvesting.inventory.stone<cost.stone||state.crystalCount<cost.crystals){toast('Faltan materiales para esta mejora.');return}harvesting.inventory.wood-=cost.wood;harvesting.inventory.stone-=cost.stone;state.crystalCount-=cost.crystals;state.tool++;harvesting.damage=state.tool+1;window.dispatchEvent(new CustomEvent('life:activity',{detail:{skill:'building',xp:50,count:1}}));save();toast('Hacha y pico mejorados.');indoor(h)})}else para('Has completado las dos mejoras del taller.');}
  extension?.indoor(h);
 }
 function collect(c){if(crystalDelay>0||c.hp===0||!nearby(c.x,c.z,c.y,2+c.size*.4))return;if(extension?.canCollect&&!extension.canCollect(c))return;crystalDelay=.7;if(!c.loose)greyMan.trigger();c.hp=Math.max(0,c.hp-(c.loose?1:1+state.tool));state.crystals[c.id]=c.hp;if(c.hp===0){c.group.visible=false;if(c.c)c.c.removed=true;state.crystalCount+=c.value;toast(`+${c.value} ${c.value===1?'cristal':'cristales'} · Para el taller o los pedestales`);updateGuides();}else toast(`Veta: ${c.hp} golpes restantes`);window.dispatchEvent(new CustomEvent('life:activity',{detail:{skill:c.loose?'exploration':'mining',xp:c.hp===0?12:3,count:c.hp===0?1:0}}));save();}
 function activate(i){if(state.runes[i]){toast('Esta runa ya está encendida.');return}const r=world.runes[i];if(!nearby(r.position.x,r.position.z,2,2.6))return;if(state.crystalCount<1){toast('Necesitas un cristal para activar este pedestal.');return}state.crystalCount--;state.runes[i]=true;glow();if(state.runes.every(Boolean)&&!state.puzzleReward){state.puzzleReward=true;state.crystalCount+=5;grant('quest:ruinas-restauradas');toast('Jardín restaurado · Costa abierta · +5 cristales')}else toast('La runa del pilar responde al pedestal.');save();}
 function find(){if(!isWalking()||dialog.open||extension?.blocked?.())return null;const p=character.position,options=[];function add(x,z,y,label,fn,range=2.1){const dist=Math.hypot(p.x-x,p.z-z);let blocked=false;if(dist<range){const dx=x-p.x,dz=z-p.z;for(const c of world.colliders){if(c.removed||p.y+.85<c.y-c.h/2||p.y+.85>c.y+c.h/2)continue;const t=T.MathUtils.clamp(((c.x-p.x)*dx+(c.z-p.z)*dz)/(dist*dist||1),0,1);if(t>.08&&t<.78&&Math.abs(p.x+dx*t-c.x)<c.w/2&&Math.abs(p.z+dz*t-c.z)<c.d/2){blocked=true;break}}}if(!blocked&&Math.abs(p.y-y)<1.6&&dist<range)options.push({x,z,y,label,fn,dist})}
  for(const h of world.buildings){add(h.x+2.7,h.z+h.d/2+1.8,2,h.stage===3?'Ver edificio':'Reparar',()=>repair(h),2.1);add(h.x,h.z+h.d/2,2,h.open?'Cerrar puerta':'Abrir puerta',()=>setDoor(h,!h.open),2);if(h.stage===3&&Math.abs(p.x-h.x)<h.w/2&&Math.abs(p.z-h.z)<h.d/2)add(h.interact.x,h.interact.z,2.12,h.interact.label,()=>indoor(h),2.1);}
  for(const c of world.collectibles)if(c.hp>0)add(c.x,c.z,c.y,c.loose?'Recoger cristal':`Picar cristal · ${c.hp}`,()=>collect(c),2+c.size*.4);
  for(let i=0;i<3;i++){const r=world.runes[i];add(r.position.x,r.position.z,2,state.runes[i]?'Runa encendida':'Activar runa · 1 cristal',()=>activate(i),2.5);}
  const extra=extension?.find();if(extra)options.push(extra);options.sort((a,b)=>a.dist-b.dist);return options[0]||null;
 }
 function act(){if(dialog.open||extension?.blocked?.())return;const selection=find();if(selection)selection.fn();else harvesting.strike();}
 function update(dt){crystalDelay=Math.max(0,crystalDelay-dt);if(restTime>0){restTime-=dt;if(restTime<=0){document.body.classList.remove('resting');toast('Descansado · Hogar fijado')}}harvesting.damage=1+state.tool+(Date.now()<restedUntil?1:0);
  for(const h of world.buildings){if(isWalking()&&h.colliders.some(c=>overlapsCollider(character.position,c,world.characterRadius??.48))){const destination=safeConstructionPosition(world,h,character.position);if(destination)moveSafely(destination);}h.doorAngle=T.MathUtils.damp(h.doorAngle,h.open?Math.PI/2:0,10,dt);h.door.rotation.y=h.doorAngle;const inside=isWalking()&&Math.abs(character.position.x-h.x)<h.w/2-.1&&Math.abs(character.position.z-h.z)<h.d/2-.1;h.inside=inside;h.roof.visible=h.stage>=2&&!inside;const dx=camera.position.x-h.x,dz=camera.position.z-h.z;h.walls.front.visible=!inside||dz<=0;h.walls.back.visible=!inside||dz>=0;h.walls.right.visible=!inside||dx<=0;h.walls.left.visible=!inside||dx>=0;}
  selected=find();marker.visible=!!selected;if(selected)marker.position.set(selected.x,selected.y+.15,selected.z);
  const harvestTarget=harvesting.getTarget();const label=selected?.label||(harvestTarget?(harvestTarget.type==='tree'?'Talar':'Picar roca'):'Interactuar');document.getElementById('contextLabel').textContent=label;document.getElementById('contextAction').disabled=!isWalking()||dialog.open||(!selected&&!harvestTarget);document.getElementById('contextHint').textContent=selected?`E · ${selected.label}`:harvestTarget?`E · ${label} · ${harvestTarget.hp}/${harvestTarget.maxHp}`:'';
 }
 function returnHome(){if(!state.home){toast('Descansa en una vivienda reparada para fijar tu hogar.');return}if(!isWalking())return;const dest=new T.Vector3(state.home.x,world.elevation(state.home.x,state.home.z),state.home.z),delta=dest.clone().sub(character.position);character.position.copy(dest);camera.position.add(delta);controls.target.add(delta);toast('Has regresado a casa.');}
 return {act,update,returnHome,state,dialog,content,openPanel,para,button,setExtension:value=>extension=value,blocked:()=>dialog.open||restTime>0,save};
}
